import{renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{impactFigure}from './eco4-figures.js?v=20261023-physicscomplete01';export function showEco4(spec='biodiversity',w={}){let [kind,card]=spec.split(':');if(card==='3'&&kind==='land-peat')kind='land-peat-cost';else if(card==='3'&&kind==='warming')kind='warming-evidence';else if(card==='3'&&kind==='waste'||card==='2'&&kind==='deforestation'||card==='2'&&kind==='warming')kind+='-data';renderDiagram(w.title||'Trace the impact',w.label||'Original educational comparison',impactFigure({kind,state:card||'0',...w}),'ECOLOGY');}
